<?php

namespace App\Tests\Unit\Infrastructure\Symfony\Filesystem;

use App\Domain\ValueObject\FilePath;
use App\Infrastructure\Symfony\Filesystem\FilePathReader;
use PHPUnit\Framework\Attributes\Test;
use PHPUnit\Framework\TestCase;
use RuntimeException;
use Symfony\Component\Filesystem\Exception\FileNotFoundException;
use Symfony\Component\Filesystem\Filesystem;

class FilePathReaderTest extends TestCase
{
    private const string TEST_IMAGE_FILENAME = 'test-image-solina-150x150.jpg';

    private string $publicImageDir;

    protected function setUp(): void
    {
        $this->publicImageDir = sys_get_temp_dir() . '/file-path-reader-test-' . uniqid('', true);

        $originFile = __DIR__ . '/' . self::TEST_IMAGE_FILENAME;
        if (!file_exists($originFile)) {
            throw new FileNotFoundException(sprintf('Error: unable to find "%s"', $originFile));
        }

        $targetFile = $this->publicImageDir . '/' . self::TEST_IMAGE_FILENAME;

        $filesystem = new Filesystem();
        $filesystem->mkdir($this->publicImageDir);
        $filesystem->copy(
            originFile: $originFile,
            targetFile: $targetFile,
        );

        if (!file_exists($targetFile)) {
            throw new FileNotFoundException(sprintf('Error: unable to find "%s"', $targetFile));
        }
    }

    protected function tearDown(): void
    {
        new Filesystem()->remove($this->publicImageDir);
    }

    #[Test]
    public function triggersRuntimeExceptionWhenFileDoesNotExists(): void
    {
        $this->expectException(RuntimeException::class);

        $filePath = $this->createMock(FilePath::class);
        $filePath
            ->expects($this->once())
            ->method('getBasename')
            ->willReturn('non-existing-basename.jpg');

        $publicImageDir = $this->publicImageDir;

        new FilePathReader($publicImageDir)->read($filePath);
    }

    #[Test]
    public function getBase64ImageAsBase64String(): void
    {
        $filePath = $this->createMock(FilePath::class);
        $filePath
            ->expects($this->once())
            ->method('getBasename')
            ->willReturn(self::TEST_IMAGE_FILENAME);

        $publicImageDir = $this->publicImageDir;

        $base64 = new FilePathReader($publicImageDir)->read($filePath);

        self::assertSame(self::getTestImageAsBase64(), $base64);
    }

    #[Test]
    public function getMimeType(): void
    {
        $filePath = $this->createMock(FilePath::class);
        $filePath
            ->expects($this->once())
            ->method('getBasename')
            ->willReturn(self::TEST_IMAGE_FILENAME);

        $publicImageDir = $this->publicImageDir;

        $mimeType = new FilePathReader($publicImageDir)->mimeType($filePath);

        self::assertSame('image/jpeg', $mimeType);
    }

    private static function getTestImageAsBase64(): string
    {
        return '';
    }
}
